B.aa_=new A.dE("G\xf3p \xfd hi\u1ec7n ch\u1ec9 \u0111\u01b0\u1ee3c ghi nh\u1eadn trong b\u1ea3n tr\u1ea3i nghi\u1ec7m.",B.bl,null)
B.aa0=new A.dE("H\u1ecfi \u0111\xe1p m\u1eabu t\u1eeb n\u1ed9i dung b\u1ed9 s\u01b0u t\u1eadp. Tr\u1ee3 l\xfd th\xf4ng minh s\u1ebd \u0111\u01b0\u1ee3c k\u1ebft n\u1ed1i sau.",B.bl,null)
B.aa1=new A.dE("D\u1eef li\u1ec7u k\u1ebft n\u1ed1i tr\u1ef1c ti\u1ebfp t\u1eeb m\xe1y ch\u1ee7 Smart Museum Guide System.",B.bl,null)
B.aa2=new A.dE("C\xe0i \u0111\u1eb7t v\xe0 d\u1eef li\u1ec7u ch\u1ec9 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean tr\u1ea3i nghi\u1ec7m hi\u1ec7n t\u1ea1i.",B.bl,null)
B.aa5=new A.dE("L\u1ed9 tr\xecnh \u0111\u01b0\u1ee3c g\u1ee3i \xfd t\u1eeb b\u1ed9 s\u01b0u t\u1eadp m\u1eabu. B\u1ea1n c\xf3 th\u1ec3 \u0111i\u1ec1u ch\u1ec9nh nh\u1ecbp tham quan t\xf9y \xfd.",B.bl,null)
B.aa6=new A.dE("B\u1ea1n c\xf3 th\u1ec3 tra c\u1ee9u b\u1ed9 s\u01b0u t\u1eadp m\xe0 kh\xf4ng c\u1ea7n c\u1ea5p quy\u1ec1n m\xe1y \u1ea3nh.",B.bl,null)
